package com.xtdpotato.xero_delta.network;
import com.xtdpotato.xero_delta.XeroDelta; import com.xtdpotato.xero_delta.block.*; import net.minecraft.core.BlockPos; import net.minecraft.network.RegistryFriendlyByteBuf; import net.minecraft.network.codec.StreamCodec; import net.minecraft.network.protocol.common.custom.CustomPacketPayload; import net.minecraft.resources.ResourceLocation; import net.minecraft.server.level.ServerPlayer; import net.neoforged.neoforge.network.handling.IPayloadContext;
public record OpenNearbyWarehousePacket() implements CustomPacketPayload{public static final Type<OpenNearbyWarehousePacket> TYPE=new Type<>(ResourceLocation.fromNamespaceAndPath(XeroDelta.MOD_ID,"open_nearby_warehouse"));public static final StreamCodec<RegistryFriendlyByteBuf,OpenNearbyWarehousePacket> STREAM_CODEC=StreamCodec.unit(new OpenNearbyWarehousePacket());public static void handle(OpenNearbyWarehousePacket packet,IPayloadContext context){if(!(context.player() instanceof ServerPlayer player))return;context.enqueueWork(()->{BlockPos center=player.blockPosition();for(BlockPos pos:BlockPos.betweenClosed(center.offset(-5,-5,-5),center.offset(5,5,5))){if(player.level().getBlockState(pos).is(ModBlocks.PERSONAL_WAREHOUSE.get())){PersonalWarehouseBlock.open(player);return;}}});}public Type<? extends CustomPacketPayload> type(){return TYPE;}}